svg.script:
// Opened as a jsDelivr URL (play.svg#<path on cdn.jsdelivr.net>), so the game runs in a jsDelivr tab.
const src = "https://cdn.jsdelivr.net/" + location.hash.slice(1);
const frame = document.getElementById("f");
// jsDelivr answers 403 for these owners' repos; esm.sh still serves them.
const ESM_SHIM = `<script>(()=>{const re=/^https:\\/\\/cdn\\.jsdelivr\\.net\\/gh\\/(?:gn-math|genizy)\\//;const fix=(u)=>{const h=new URL(u,document.baseURI).href;return re.test(h)?"https://esm.sh/gh/"+h.slice(28)+(h.includes("?")?"&raw":"?raw"):u};const f=fetch;window.fetch=(i,o)=>f(typeof i==="string"||i instanceof URL?fix(String(i)):i,o);const x=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,u,...r){return x.call(this,m,fix(u),...r)}})()<\/script>`;
fetch(src).then((r) => r.ok ? r.text() : Promise.reject(new Error("HTTP " + r.status))).then((html) => {
  const head = (/<base\s/i.test(html) ? "" : '<base href="' + src.replace(/[^/]*$/, "") + '">') + ESM_SHIM;
  frame.srcdoc = /<head[^>]*>/i.test(html) ? html.replace(/<head[^>]*>/i, (m) => m + head) : head + html;
}).catch((e) => { frame.srcdoc = "Couldn't load " + src.replace(/[<&]/g, "") + ": " + e.message; });
